+export async function listTools() {
+  return [
+    {
+      name: 'echo',
+      description: 'Echo back the provided message',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          message: { type: 'string', description: 'The message to echo back' }
+        },
+        required: ['message'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args) {
+  const arguments_ = args || {};
+  if (name === 'echo') {
+    if (typeof arguments_.message !== 'string') {
+      const err = new Error('Invalid arguments: "message" must be a string');
+      err.code = -32602;
+      throw err;
+    }
+    return { content: [{ type: 'text', text: arguments_.message }] };
+  }
+  const err = new Error(`Unknown tool: ${name}`);
+  err.code = -32601;
+  throw err;
+}
